// TestWorkbookCopyDryRun verifies the --dry-run plan: prints the copy-then-
// reassign intent and exits 0 without any HTTP.
func TestWorkbookCopyDryRun(t *testing.T) {
	t.Setenv("PRINTING_PRESS_VERIFY", "")
	cmd := RootCmd()
	var buf bytes.Buffer
	cmd.SetOut(&buf)
	cmd.SetErr(&buf)
	cmd.SetArgs([]string{"workbook", "copy", "2Xpsl5dB1qD", "--to", "analyst@acme.com", "--dry-run"})
	if err := cmd.Execute(); err != nil {
		t.Fatalf("dry-run execute error = %v", err)
	}
	out := buf.String()
	if !strings.Contains(out, "would copy") {
		t.Errorf("expected 'would copy' in output, got:\n%s", out)
	}
	if !strings.Contains(out, "reassign owner to analyst@acme.com") {
		t.Errorf("expected reassign-to recipient in output, got:\n%s", out)
	}
}

